sys_ws_operation.operation_script:
(function process( /*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {

    // implement resource here
    var pathParams = request.pathParams;
    var number = pathParams.number;

    var gr = new GlideRecord('x_58872_needit_needit');
    gr.get('number', number);

    if (!gs.nil(gr.sys_id)) {
        response.setContentType('application/json');
        response.setStatus(200);
        var body = {};
        body.number = gr.getDisplayValue('number');
        body.short_description = gr.getDisplayValue('short_description');
        response.setBody(body);
		return;
    } else {
		var resError = responseError(404,`NeedIt record ${number} NOT FOUND!`,"Detail info here");
        response.setError(resError);
    }

    function responseError(status, message, detail) {
		var status = status || 500;
		var message = message || "Error Message";
		var detail = detail || "Detail";

        var myError = new sn_ws_err.ServiceError();
        myError.setStatus(status);
        myError.setMessage(message);
        myError.setDetail(detail);
		return myError;
    }

})(request, response);
